export function lookupPM25(lat, lng) {
  const { lats, lons, grid } = PM25_GRID;
  let iL = 0,
    dL = Infinity;
  for (let i = 0; i < lats.length; i++) {
    const d = Math.abs(lats[i] - lat);
    if (d < dL) {
      dL = d;
      iL = i;
    }
  }
  let iG = 0,
    dG = Infinity;
  for (let j = 0; j < lons.length; j++) {
    const d = Math.abs(lons[j] - lng);
    if (d < dG) {
      dG = d;
      iG = j;
    }
  }
  const v = grid[iL]?.[iG];
  return v === null || v === undefined ? null : Math.round(v * 10) / 10;
}
export function getPM25Risk(pm25) {
  if (pm25 === null || pm25 === undefined)
    return {
      label: "No data",
      short: "N/A",
      color: "#6B7280",
      bg: "#F3F4F6",
      bar: "#D1D5DB",
    };
  if (pm25 <= 15)
    return {
      label: "Meets WHO standard",
      short: "Good",
      color: "#166534",
      bg: "#F0FDF4",
      bar: "#22C55E",
    };
  if (pm25 <= 25)
    return {
      label: "Slightly above WHO",
      short: "Mild",
      color: "#1D4ED8",
      bg: "#EFF6FF",
      bar: "#60A5FA",
    };
  if (pm25 <= 35)
    return {
      label: "Moderately above WHO",
      short: "Mod",
      color: "#92400E",
      bg: "#FFFBEB",
      bar: "#F59E0B",
    };
  return {
    label: "Severely above WHO",
    short: "High",
    color: "#9B1C1C",
    bg: "#FEF2F2",
    bar: "#EF4444",
  };
}
// NOTE: A composite "Exposure Score" (weighted blend of road distance +
